import {resolve as resolveScriptPath} from "node:path";
import {pathToFileURL as scriptURL} from "node:url";
import {randomBytes} from "node:crypto";
import {DatabaseSync} from "node:sqlite";
import {existsSync,writeFileSync,unlinkSync} from "node:fs";
import {join} from "node:path";
import {createFixture,safeDiagnostic} from "../e2e/lifecycle.mjs";
let f,failure,current="setup";const images=[];let arbitraryRequests=0;
const check=(value,label)=>{if(!value)throw new Error(`Expected ${label}; observed false`);};
const step=async(name,run)=>{current=name;await run();console.log(`PASS ${name}`);};
const button=(page,name)=>page.getByRole("button",{name,exact:true});
const field=(page,name)=>page.getByLabel(name,{exact:true});
const press=(page,name)=>button(page,name).press("Enter");
async function capture(context){for(const cookie of await context.cookies())if(cookie.name!=="watchnext_access_mode"&&!f.secrets.includes(cookie.value))f.secrets.push(cookie.value);}
async function register(page,name,password){await page.goto(f.origin+"/register");await field(page,"Username").fill(name);await field(page,"Password").fill(password);await field(page,"Confirm password").fill(password);await press(page,"Create account");const code=field(page,"Private recovery code");await code.waitFor();f.secrets.push(await code.inputValue());await capture(page.context());await page.getByRole("link",{name:/Continue/}).press("Enter");await page.waitForURL("**/account");}
async function create(page,name){await page.goto(f.origin+"/account");await field(page,"New group name").fill(name);await press(page,"Create account group");const link=field(page,"Invite link");await link.waitFor();const invite=await link.inputValue();f.secrets.push(invite.split("/").at(-1));await capture(page.context());return invite;}
async function open(page,name){await page.goto(f.origin+"/account");await press(page,`Open ${name}`);await page.waitForURL("**/group");await page.getByRole("heading",{name,exact:true}).waitFor();await capture(page.context());}
async function add(page,source="youtube",query="YtFixture01",kind="link") {await page.goto(f.origin+"/watchlist/add");await field(page,"Entry method").selectOption(source);if(source==="youtube") {await field(page,"YouTube lookup").selectOption(kind);await field(page,kind==="title"?"YouTube title":"YouTube video link or ID").fill(query);}else await field(page,"Title to search").fill(query);await press(page,source==="youtube"&&kind==="link"?"Look up video":"Search titles");}
async function review(page){const handle=page.locator('input[name="reviewHandle"]');await handle.waitFor({state:"attached"});f.secrets.push(await handle.inputValue());}
async function save(page){await press(page,"Save title");await page.waitForURL("**/watchlist/add?saved=*");return new URL(page.url()).searchParams.get("saved");}
async function detail(page,id){await page.goto(f.origin+"/watchlist/"+id);}
async function image(page,title){const img=page.getByRole("img",{name:`${title} cover`,exact:true});await img.scrollIntoViewIfNeeded();await page.waitForFunction(title=>{const img=[...document.images].find(item=>item.alt===title+" cover");return img?.naturalWidth>0;},title);check(await img.getAttribute("referrerpolicy")==="no-referrer","preview uses no-referrer");return img;}
async function markers(){const ready=join(f.root,"provider-waiting"),release=join(f.root,"provider-release");for(const path of[ready,release,join(f.root,"provider-returned")])if(existsSync(path))unlinkSync(path);return{ready,release};}
async function waitFile(path){const until=Date.now()+4000;while(!existsSync(path)){if(Date.now()>until)throw new Error("Outbound gate did not start");await new Promise(done=>setTimeout(done,20));}}
export async function runAutofill({build=true,onFixture,injectFailure=false}={}){
failure=undefined;current="setup";

try{
 f=await createFixture();onFixture?.(f);await step("current production build and isolated server",async()=>{await (build?f.build():f.initialize());await f.launch();await f.start();});
 for(const width of[375,1280]){
  const contexts=[await f.context(width),await f.context(width)];
  for(const context of contexts)for(const pattern of["https://i.ytimg.com/**","https://kinopoiskapiunofficial.tech/images/**","https://avatars.mds.yandex.net/**"])await context.route(pattern,async route=>{images.push({referer:Boolean(route.request().headers().referer),host:new URL(route.request().url()).hostname});if(route.request().url().includes("broken"))return route.fulfill({status:200,contentType:"image/png",body:"broken image"});return route.fulfill({status:200,contentType:"image/svg+xml",body:'<svg xmlns="http://www.w3.org/2000/svg" width="160" height="240"><rect width="160" height="240" fill="#eaf0ff"/><rect x="12" y="12" width="136" height="216" rx="8" fill="#1d4ed8"/><path d="M60 90L110 120L60 150Z" fill="white"/></svg>'});});
  for(const context of contexts)await context.route("https://example.com/**",route=>{arbitraryRequests++;return route.abort();});
  const[a,b]=await Promise.all(contexts.map(context=>context.newPage())),group=`Discovery shared ${width}`,other=`Discovery other ${width}`,password=randomBytes(24).toString("base64url");f.secrets.push(password);let film,video,series;
  await step(`${width}: two real accounts and independent groups`,async()=>{await register(a,`DiscoveryA.${width}`,password);const invite=await create(a,group);await open(a,group);await register(b,`DiscoveryB.${width}`,password);await b.goto(invite);await b.waitForURL("**/account");await press(b,`Join ${group}`);await b.waitForURL("**/group");await capture(contexts[1]);await create(b,other);await open(b,group);});
  await step(`${width}: title candidates, safe images, exact autofill, moods and explicit save`,async()=>{
   current="YT search result";await add(a,"youtube","find videos","title");await button(a,"Review Synthetic YouTube proposal").waitFor();check(await field(a,"Title").inputValue()==="","search never auto-selects");check((await a.getByRole("region",{name:"Search results"}).innerText()).includes("Synthetic channel · 2 min"),"actual channel and runtime candidate hints");await image(a,"Synthetic YouTube proposal");current="YT exact selection";await press(a,"Review Synthetic exact video");await review(a);check(await field(a,"Title").inputValue()==="Synthetic exact video"&&await field(a,"Minutes").inputValue()==="4"&&await field(a,"Seconds (optional)").inputValue()==="5","selected detail automatically fills exact editable duration");check(await button(a,"Apply proposal and replace details").count()===0&&await button(a,"Replace details").count()===0,"clean path has no second approval");check(!await field(a,"Funny").isChecked(),"provider never preselects moods");current="YT missing mood gate";await press(a,"Save title");await a.getByRole("alert").filter({hasText:/mood/i}).waitFor();await review(a);check(await field(a,"Title").inputValue()==="Synthetic exact video","server mood error preserves imported fields");await field(a,"Funny").check();current="YT actual save";video=await save(a);check(f.db.prepare("SELECT duration_seconds,provider_id FROM titles WHERE id=?").get(video).duration_seconds===245,"real trusted save keeps exact runtime");current="YT broken saved cover";await detail(a,video);await a.locator(".detail-metadata .title-cover").scrollIntoViewIfNeeded();await a.locator(".cover-fallback").filter({hasText:"No cover"}).waitFor();
   current="YT direct link";await add(a,"youtube","YtFixture01");await review(a);check(await field(a,"Title").inputValue()==="Synthetic YouTube proposal","direct link automatically fills clean form");await image(a,"Synthetic YouTube proposal");check((await a.locator(".lookup-review .title-cover").getAttribute("class")).includes("video-cover"),"video preview has fixed video shape");
  });
  await step(`${width}: dirty replacement, pending edit protection and canceled late responses`,async()=>{
   await field(a,"Title").fill("My corrected video");await field(a,"Funny").check();await field(a,"YouTube video link or ID").fill("YtExact0001");await press(a,"Look up video");await button(a,"Keep my details").waitFor();const old=await a.locator('input[name="reviewHandle"]').inputValue();await press(a,"Keep my details");check(await field(a,"Title").inputValue()==="My corrected video"&&await a.locator('input[name="reviewHandle"]').inputValue()===old,"decline preserves fields and old trusted review");await press(a,"Look up video");await press(a,"Replace details");await review(a);check(await field(a,"Funny").isChecked(),"replacement retains manual moods");
   let gate=await markers();await field(a,"YouTube video link or ID").fill("YtHolding01");await press(a,"Look up video");await waitFile(gate.ready);await field(a,"Title").fill("Edit made while waiting");writeFileSync(gate.release,"release");await button(a,"Replace details").waitFor();check(await field(a,"Title").inputValue()==="Edit made while waiting","late selected detail never overwrites a newer edit");check(await field(a,"Title").evaluate(element=>element===document.activeElement),"late result does not steal focus while editing");await press(a,"Keep my details");
   gate=await markers();await field(a,"YouTube video link or ID").fill("YtHolding01");await press(a,"Look up video");await waitFile(gate.ready);await press(a,"Cancel lookup");await field(a,"Title").fill("After cancellation");writeFileSync(gate.release,"release");await waitFile(join(f.root,"provider-returned"));check(await field(a,"Title").inputValue()==="After cancellation","canceled normal provider response cannot overwrite edits");
   await press(a,"Start a fresh manual entry (clear details)");await press(a,"Keep editing");check(await field(a,"Title").inputValue()==="After cancellation","fresh manual cancel retains dirty details");await press(a,"Start a fresh manual entry (clear details)");await press(a,"Clear details and start manually");check(await a.locator('input[name="reviewHandle"]').count()===0,"explicit fresh reset drops imported authority");
  });
  await step(`${width}: real empty/previous/next pages and bounded five-visit limit for both sources`,async()=>{
   for(const source of["youtube","kinopoisk_unofficial"]){current=`${width}: ${source} empty/paging`;await add(a,source,"empty", "title");await a.getByText(/No matching titles on this page/).waitFor();await press(a,"Next page");await a.getByRole("navigation",{name:"Search pages"}).getByText("Page 2",{exact:true}).waitFor();await press(a,"Previous page");await a.getByText(/No matching titles on this page/).waitFor();await press(a,"Next page");await press(a,"Next page");await a.getByText(/Page limit reached/).waitFor();check(await button(a,"Next page").count()===0&&await button(a,"Previous page").count()===0,"exhausted chain exposes no fake paging actions");}
  });
  await step(`${width}: Kinopoisk automatic film and manually completed series, preview surfaces and shared dedup`,async()=>{
   await add(a,"kinopoisk_unofficial","ambiguous");await press(a,"Review Synthetic ambiguous film (2001)");await review(a);check(await field(a,"Minutes").inputValue()==="120"&&await field(a,"Genres (optional)").inputValue()==="Drama","film runtime and genres automatically fill");await a.getByText(/runtime interprets.*minutes/).waitFor();await image(a,"Synthetic ambiguous film");await field(a,"Funny").check();film=await save(a);check(f.db.prepare("SELECT origin FROM metadata_fields WHERE title_id=? AND field='coverUrl'").get(film).origin==="provider","unchanged poster has provider ownership");
   for(const path of["/watchlist","/watchlist/"+film]){await a.goto(f.origin+path);await image(a,"Synthetic ambiguous film");}
   current="KP same provider identity save";await add(b,"kinopoisk_unofficial","ambiguous");await press(b,"Review Synthetic ambiguous film (2001)");await review(b);await field(b,"Funny").check();await press(b,"Save title");await b.waitForURL("**/watchlist/"+film);check(f.db.prepare("SELECT count(*) AS n FROM contributors WHERE title_id=?").get(film).n===2,"exact trusted provider identity shares one title without extra ambiguity");await press(b,"Remove my contribution");await press(b,"Confirm removal");await b.getByRole("status").filter({hasText:/contribution was removed/}).waitFor();
   current="KP manual ambiguity confirmation";await b.goto(f.origin+"/watchlist/add");await field(b,"Title").fill("Synthetic ambiguous film");await field(b,"Minutes").fill("120");await field(b,"Funny").check();await press(b,"Save title");await button(b,"Add my name to this title").waitFor();check(f.db.prepare("SELECT count(*) AS n FROM contributors WHERE title_id=?").get(film).n===1,"ambiguity confirmation has not written");await press(b,"Return to editing");await press(b,"Save title");await press(b,"Add my name to this title");await b.waitForURL("**/watchlist/"+film);check(f.db.prepare("SELECT count(*) AS n FROM contributors WHERE title_id=?").get(film).n===2,"confirmed manual duplicate preserves shared identity and attribution");
   current="KP series runtime and confirmation gates";await add(a,"kinopoisk_unofficial","series");await press(a,"Review Synthetic episodic series (2001)");await review(a);check(await field(a,"Minutes").inputValue()===""&&await field(a,"Episode numbering").inputValue()==="","no inferred episode runtime/numbering");await field(a,"Funny").check();await press(a,"Save title");await a.getByRole("alert").filter({hasText:/duration|minutes/i}).waitFor();await field(a,"Minutes").fill("22");await field(a,"Episode numbering").selectOption("continuous");await press(a,"Save title");await a.getByRole("alert").filter({hasText:/typical/i}).waitFor();await field(a,"I confirm this is a typical episode duration").check();series=await save(a);check(f.db.prepare("SELECT duration_seconds FROM titles WHERE id=?").get(series).duration_seconds===1320,"manual episode completion saved");
  });
  await step(`${width}: archive/restore, real expiry versus authored cover and foreign-group isolation`,async()=>{
   for(const page of[a,b]){await detail(page,film);await press(page,"Remove my contribution");await press(page,"Confirm removal");await page.getByRole("status").filter({hasText:/removed|archived/i}).waitFor();}await a.goto(f.origin+"/archive");await image(a,"Synthetic ambiguous film");await detail(a,film);await image(a,"Synthetic ambiguous film");
   await a.goto(f.origin+"/watchlist/add");await field(a,"Title").fill("Synthetic ambiguous film");await field(a,"Minutes").fill("120");await field(a,"Funny").check();await press(a,"Save title");await button(a,"Restore to watchlist").waitFor();await press(a,"Return to editing");check(f.db.prepare("SELECT archived FROM titles WHERE id=?").get(film).archived===1,"cancel leaves archive unchanged");await press(a,"Save title");await press(a,"Restore to watchlist");await a.waitForURL("**/watchlist/"+film+"?contribution=saved");
   const write=new DatabaseSync(f.path);try{write.exec("PRAGMA busy_timeout=5000");write.prepare("UPDATE metadata_fields SET expires_at='2000-01-01T00:00:00Z' WHERE title_id=? AND field='coverUrl' AND origin='provider'").run(film);}finally{write.close();}await a.reload();check(await a.getByRole("img",{name:"Synthetic ambiguous film cover",exact:true}).count()===0,"expired provider poster renders fallback");check(f.db.prepare("SELECT cover_url FROM titles WHERE id=?").get(film).cover_url===null,"expired poster physically cleared");
   await open(b,other);await add(b,"kinopoisk_unofficial","ambiguous");await press(b,"Review Synthetic ambiguous film (2001)");await review(b);await field(b,"Cover image link (optional)").fill("https://avatars.mds.yandex.net/get-kinopoisk-image/4303601/authored-correction-42/orig");await field(b,"Funny").check();const corrected=await save(b);check(f.db.prepare("SELECT origin FROM metadata_fields WHERE title_id=? AND field='coverUrl'").get(corrected).origin==="user","actual cover correction belongs to user");await detail(b,corrected);await image(b,"Synthetic ambiguous film");
   await b.goto(f.origin+"/watchlist/"+corrected+"/edit");await field(b,"Cover image link (optional)").fill("https://example.com/authored-cover.png");await press(b,"Save changes");await b.waitForURL(url=>url.pathname==="/watchlist/"+corrected);await b.locator(".cover-fallback").filter({hasText:"No cover"}).waitFor();check(f.db.prepare("SELECT cover_url FROM titles WHERE id=?").get(corrected).cover_url==="https://example.com/authored-cover.png"&&arbitraryRequests===0,"unsupported authored URL remains stored but is never requested");
   await b.goto(f.origin+"/watchlist/"+corrected+"/edit");await field(b,"Cover image link (optional)").fill("https://avatars.mds.yandex.net/get-kinopoisk-image/4303601/authored-correction-42/orig");await press(b,"Save changes");await b.waitForURL(url=>url.pathname==="/watchlist/"+corrected);
   const expiry=new DatabaseSync(f.path);try{expiry.exec("PRAGMA busy_timeout=5000");expiry.prepare("UPDATE metadata_fields SET expires_at='2000-01-01T00:00:00Z' WHERE title_id=? AND origin='provider'").run(corrected);}finally{expiry.close();}await b.reload();await image(b,"Metadata unavailable");check(f.db.prepare("SELECT cover_url FROM titles WHERE id=?").get(corrected).cover_url.includes("authored-correction-42"),"allowed user correction survives actual provider expiry");await detail(a,corrected);await a.getByRole("heading",{name:"Title unavailable",exact:true}).waitFor();await detail(b,film);await b.getByRole("heading",{name:"Title unavailable",exact:true}).waitFor();
   await detail(a,video);check(await a.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),"details fit viewport");await a.goto(f.origin+"/watchlist/add");await field(a,"Title").focus();check(await field(a,"Title").evaluate(element=>{const style=getComputedStyle(element);return style.outlineStyle!=="none"||style.boxShadow!=="none";}),"keyboard focus remains visible");await add(a,"kinopoisk_unofficial","ambiguous");await button(a,"Review Synthetic ambiguous film (2001)").waitFor();check(await a.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),"candidate cards fit viewport");if(process.env.WATCHNEXT_VISUAL_CHECK)await a.screenshot({path:join(f.root,`previews-${width}.png`),fullPage:true});
  });
  for(const context of contexts)await context.close();
 }
 check(images.length>0&&images.every(image=>!image.referer),"actual browser previews never send referrer");
 if(process.env.WATCHNEXT_VISUAL_CHECK){console.log("VISUAL "+f.root);await new Promise(done=>setTimeout(done,30000));}
 await f.audit();
}catch(error){failure=error;}finally{try{await f?.cleanup();}catch(error){failure??=error;}}
if(failure)throw new Error(`FAIL ${current}: ${safeDiagnostic(failure,f?.secrets??[],f?.root??"",f?[f.sentinelRoot]:[])}; owned cleanup complete: ${f?.cleanupComplete??false}`);
const report={pass:true,widths:[375,1280],twoAccountsTwoGroups:true,bothProviderPaths:true,realPagingAutofillDirtyRace:true,previewsDedupArchiveExpiry:true,privacyAudit:true,ownedCleanup:f.cleanupComplete};console.log(JSON.stringify(report));return report;
}
if(process.argv[1]&&scriptURL(resolveScriptPath(process.argv[1])).href===import.meta.url)runAutofill().catch(error=>{console.error(error.message);process.exitCode=1;});
